/* Valorisation par cap rate : V = NOI/cap en fonction du cap rate */
(function () {
  var svg = document.getElementById("im-chart");
  if (!svg) return;
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function al(){ return document.body.getAttribute("data-active-lang")||"fr"; }

  function draw(){
    var NOI=v("im-noi"), cap=v("im-cap")/100;
    setT("im-noi-o", NOI.toFixed(0)); setT("im-cap-o",(cap*100).toFixed(2)+"%");
    var val = NOI/cap;
    setT("im-val", val.toFixed(0)+" k€"); setT("im-yield",(NOI/val*100).toFixed(2)+"%");

    var W=520,H=260,L=52,R=14,T=14,B=32, pw=W-L-R, ph=H-T-B;
    var xmin=0.02, xmax=0.12;
    var ymax = NOI/xmin;                  // valeur max à cap min
    function px(x){ return L + (x-xmin)/(xmax-xmin)*pw; }
    function py(y){ return T + (1-Math.min(y,ymax)/ymax)*ph; }

    var g2="";
    g2+='<line class="axis" x1="'+L+'" y1="'+T+'" x2="'+L+'" y2="'+(T+ph)+'"/>';
    g2+='<line class="axis" x1="'+L+'" y1="'+(T+ph)+'" x2="'+(L+pw)+'" y2="'+(T+ph)+'"/>';
    // courbe V(cap)
    var N=120, d="";
    for (var i=0;i<=N;i++){
      var cc = xmin + (xmax-xmin)*i/N;
      var vv = NOI/cc;
      d += (d===""?"M ":" L ")+px(cc).toFixed(1)+","+py(vv).toFixed(1);
    }
    g2+='<path d="'+d+'" fill="none" stroke="var(--teal)" stroke-width="2.6"/>';
    // point courant
    if (cap>=xmin && cap<=xmax){
      g2+='<circle cx="'+px(cap).toFixed(1)+'" cy="'+py(val).toFixed(1)+'" r="4" fill="var(--ink)"/>';
      g2+='<line class="axis" x1="'+px(cap).toFixed(1)+'" y1="'+py(val).toFixed(1)+'" x2="'+px(cap).toFixed(1)+'" y2="'+(T+ph)+'" stroke-dasharray="3 3" stroke-width="1"/>';
    }
    // ticks x
    g2+='<text class="tick" x="'+L+'" y="'+(H-16)+'" text-anchor="start">'+(xmin*100).toFixed(0)+'%</text>';
    g2+='<text class="tick" x="'+(L+pw)+'" y="'+(H-16)+'" text-anchor="end">'+(xmax*100).toFixed(0)+'%</text>';
    // ticks y
    g2+='<text class="tick" x="'+(L-6)+'" y="'+(py(ymax)+4).toFixed(1)+'" text-anchor="end">'+ymax.toFixed(0)+'</text>';
    g2+='<text class="tick" x="'+(L-6)+'" y="'+(py(0)+0).toFixed(1)+'" text-anchor="end">0</text>';
    var xlab = al()==="en"?"cap rate":(al()==="nl"?"cap rate":"taux de capitalisation");
    var ylab = al()==="en"?"value (k€)":(al()==="nl"?"waarde (k€)":"valeur (k€)");
    g2+='<text class="lab" x="'+(L+pw/2)+'" y="'+(H-3)+'" text-anchor="middle">'+xlab+'</text>';
    g2+='<text class="lab" x="'+(L-40)+'" y="'+(T+ph/2)+'" text-anchor="middle" transform="rotate(-90 '+(L-40)+' '+(T+ph/2)+')">'+ylab+'</text>';
    svg.innerHTML=g2;
  }

  ["im-noi","im-cap"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
